import{_ as s,o as t,c as a,l as n,t as o,N as r}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"sysvipc | x-cmd man (man7) | System V interprocess communication mechanisms","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | sysvipc - System V interprocess communication mechanisms","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"sysvipc | x-cmd man (man7) | System V interprocess communication mechanisms"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | sysvipc - System V interprocess communication mechanisms"}]]},"headers":[],"params":{"isMan":true,"man":"sysvipc","category":"man7","desc":"System V interprocess communication mechanisms"},"relativePath":"man7/sysvipc.md","filePath":"man7/sysvipc.md"}'),i={name:"man7/sysvipc.md"},m={class:"visually-hidden"},d=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>sysvipc - System V interprocess communication mechanisms</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>System V IPC is the name given to three interprocess communication mechanisms that are widely available on UNIX systems: message queues, semaphore, and shared memory.</p><h3 id="message-queues" tabindex="-1">Message queues <a class="header-anchor" href="#message-queues" aria-label="Permalink to &quot;Message queues&quot;">​</a></h3><p>System V message queues allow data to be exchanged in units called messages. Each message can have an associated priority. POSIX message queues provide an alternative API for achieving the same result; see <strong>mq_overview</strong>(7).</p><p>The System V message queue API consists of the following system calls:</p><dl><dt><strong>msgget</strong>(2)</dt><dd>Create a new message queue or obtain the ID of an existing message queue. This call returns an identifier that is used in the remaining APIs.</dd><dt><strong>msgsnd</strong>(2)</dt><dd>Add a message to a queue.</dd><dt><strong>msgrcv</strong>(2)</dt><dd>Remove a message from a queue.</dd><dt><strong>msgctl</strong>(2)</dt><dd>Perform various control operations on a queue, including deletion.</dd></dl><h3 id="semaphore-sets" tabindex="-1">Semaphore sets <a class="header-anchor" href="#semaphore-sets" aria-label="Permalink to &quot;Semaphore sets&quot;">​</a></h3><p>System V semaphores allow processes to synchronize their actions. System V semaphores are allocated in groups called sets; each semaphore in a set is a counting semaphore. POSIX semaphores provide an alternative API for achieving the same result; see <strong>sem_overview</strong>(7).</p><p>The System V semaphore API consists of the following system calls:</p><dl><dt><strong>semget</strong>(2)</dt><dd>Create a new set or obtain the ID of an existing set. This call returns an identifier that is used in the remaining APIs.</dd><dt><strong>semop</strong>(2)</dt><dd>Perform operations on the semaphores in a set.</dd><dt><strong>semctl</strong>(2)</dt><dd>Perform various control operations on a set, including deletion.</dd></dl><h3 id="shared-memory-segments" tabindex="-1">Shared memory segments <a class="header-anchor" href="#shared-memory-segments" aria-label="Permalink to &quot;Shared memory segments&quot;">​</a></h3><p>System V shared memory allows processes to share a region a memory (a &quot;segment&quot;). POSIX shared memory is an alternative API for achieving the same result; see <strong>shm_overview</strong>(7).</p><p>The System V shared memory API consists of the following system calls:</p><dl><dt><strong>shmget</strong>(2)</dt><dd>Create a new segment or obtain the ID of an existing segment. This call returns an identifier that is used in the remaining APIs.</dd><dt><strong>shmat</strong>(2)</dt><dd>Attach an existing shared memory object into the calling process&#39;s address space.</dd><dt><strong>shmdt</strong>(2)</dt><dd>Detach a segment from the calling process&#39;s address space.</dd><dt><strong>shmctl</strong>(2)</dt><dd>Perform various control operations on a segment, including deletion.</dd></dl><h3 id="ipc-namespaces" tabindex="-1">IPC namespaces <a class="header-anchor" href="#ipc-namespaces" aria-label="Permalink to &quot;IPC namespaces&quot;">​</a></h3><p>For a discussion of the interaction of System V IPC objects and IPC namespaces, see <strong>ipc_namespaces</strong>(7).</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>ipcmk</strong>(1), <strong>ipcrm</strong>(1), <strong>ipcs</strong>(1), <strong>lsipc</strong>(1), <strong>ipc</strong>(2), <strong>msgctl</strong>(2), <strong>msgget</strong>(2), <strong>msgrcv</strong>(2), <strong>msgsnd</strong>(2), <strong>semctl</strong>(2), <strong>semget</strong>(2), <strong>semop</strong>(2), <strong>shmat</strong>(2), <strong>shmctl</strong>(2), <strong>shmdt</strong>(2), <strong>shmget</strong>(2), <strong>ftok</strong>(3), <strong>ipc_namespaces</strong>(7)</p>',20);function c(e,g,h,l,p,u){return t(),a("div",null,[n("h1",m,o(e.$params.man),1),d])}const v=s(i,[["render",c]]);export{f as __pageData,v as default};
